from future.utils import with_metaclass

from abc import abstractmethod
from lxml import etree
import json
from abc import ABCMeta
import os
from collections import namedtuple
from ta5g_delta.convert_delta import ManagedObject

XmlWriterSpecificData = namedtuple('XmlWriterData', ['class_name', 'version'])


class Reader(with_metaclass(ABCMeta, object)):
    def read(self, filepath):
        assert os.path.isfile(filepath), 'Given filepath does not exist: {}'.format(filepath)
        return self._read(filepath)

    @abstractmethod
    def _read(self, filepath):
        raise NotImplementedError


class XmlReader(Reader):
    def __init__(self):
        self._stored_data = {}

    def _convert_xml_to_dicts(self, filepath):
        document_root = etree.parse(filepath)
        managed_objects = self._process_document(document_root)
        dicts = json.dumps(managed_objects, sort_keys=True, indent=4, separators=(',', ': '))
        return json.loads(dicts)

    def _rename_dicts(self, filepath):
        dicts = self._convert_xml_to_dicts(filepath)
        for moc in dicts:
            for param in moc["parameters"]:
                if param['value'] is None:
                    param['operation'] = 'delete'
        return dicts

    def _process_document(self, document_root):
        managed_objects = []

        for element in document_root.iter('{*}managedObject'):
            self._store_document_element_specific_data(element)
            managed_objects.append(ManagedObject(element))
        return managed_objects

    def _store_document_element_specific_data(self, element):
        dist_name = element.attrib.get('distName')
        class_name = element.attrib.get('class')
        version = element.attrib.get('version')
        self._stored_data[dist_name] = XmlWriterSpecificData(class_name, version)

    def _read(self, filepath):
        return self._rename_dicts(filepath), self._stored_data


class JsonReader(Reader):
    def _read(self, filepath):
        with open(filepath) as f:
            lines = f.read()
        return json.loads(lines), None
